import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtil from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<Object>} [textContent]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Object} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---- Plane ----
  const aspect = 512 / 320; // from atlas source rect
  const width = aspect; // 1.6 units width
  const height = 1; // 1 unit height
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
  });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Text ----
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // ---- Rotation & Scale (position applied by adapter) ----
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  // ---- Handlers placeholder ----
  root.userData.handlers = {};

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was set
    if (material.map) {
      material.map.dispose();
    }

    // Remove and dispose text objects
    for (const txt of textObjects) {
      if (txt.parent) txt.parent.remove(txt);
    }

    // Kill any GSAP timelines (none in this node)
    if (root.userData._gsapTimeline) {
      root.userData._gsapTimeline.kill();
    }
  };

  return root;
}
